<script lang="ts">
 import { page } from '$app/state';
 import { replaceState } from '$app/navigation';
 import { untrack } from 'svelte';
 import { board } from '$lib/board.svelte';
 import '$lib/research.css';
 import AttachmentPreview from '$lib/components/AttachmentPreview.svelte';
 import { readAttachmentFiles } from '$lib/attachments';
 import type { UserAttachment } from '$lib/types';
 import TargetBindings from '$lib/components/research/TargetBindings.svelte';
 import ProjectLiterature from '$lib/components/research/ProjectLiterature.svelte';
 import { researchApi, runLabel, isRunActive, runContactNotice, type ProjectResearchRefs, type ResearchExperiment, type ResearchFile, type ResearchLog, type ResearchMetrics, type ResearchProject, type ResearchRun, type ResearchSnapshot, type ResearchStatus, type ResearchTarget } from '$lib/research';
 import { buildExperimentTree, phaseLabel, latestDoneRun, metricDelta, stableRunSequence, availableTarget } from '$lib/research-guide';
 const id = $derived(page.params.id ?? '');
 const host = $derived(page.url.searchParams.get('host') || board.origin || undefined);
 let project = $state<ResearchProject | null>(null);
 let status = $state<ResearchStatus | null>(null);
 let experiments = $state.raw<ResearchExperiment[]>([]);
 let runs = $state.raw<ResearchRun[]>([]);
 let files = $state.raw<ResearchFile[]>([]);
 let refs = $state.raw<ProjectResearchRefs>({ literature: [], experiments: {}, settings: { primaryMetric: null, metricDirections: {}, metricUnits: {} } });
 let targets = $state<ResearchTarget[]>([]);
 let selectedExperiment = $state('');
 let activeTab = $state<'overview'|'experiments'|'literature'|'chat'>('experiments');
 let chatDraft=$state(''); let chatError = $state(''); let chatBusy = $state(false);
 let selectedPaperId = $state(''); let selectedArtifactPath = $state('');
 let selectedTarget = $state('');
 let snapshot = $state<ResearchSnapshot | null>(null);
 let metrics = $state<Record<string, ResearchMetrics>>({});
 let openRuns = $state<string[]>([]);
 let selectedRun = $state('');
 let log = $state<ResearchLog | null>(null);
 let logStart = $state(0);
 let logError = $state(''); let logPanel=$state<HTMLDivElement|null>(null); let followLog=true;
 let error = $state('');
 let busy = $state(false);
 let pendingCancel = $state<string[]>([]); let pendingReconnect = $state<string[]>([]);
 let title = $state(''); let description = $state(''); let command = $state(''); let parentId = $state('');
 let metricName = $state(''); let metricUnit = $state(''); let metricDirection = $state<'higher'|'lower'>('higher');
 let dashboardUrl = $state('');let artifactPreview=$state<{openPreview:(attachment:UserAttachment,trigger:HTMLButtonElement)=>void}|null>(null);let artifactToken=0;
 const currentLink=$derived<ProjectResearchRefs['experiments'][string]>(refs.experiments[selectedExperiment]||{literatureIds:[],artifactPaths:[]});
 let generation = 0; let logToken = 0; let refreshSequence = 0; let mutationVersion = 0; let timer: ReturnType<typeof setInterval> | undefined;
 const seq = $derived(stableRunSequence(runs));
 const chosen = $derived(experiments.find((item) => item.id === selectedExperiment) ?? null);
 const scopedRuns = $derived(runs.filter((run) => !selectedExperiment || run.experimentId === selectedExperiment));
 const latestRun = $derived(latestDoneRun(scopedRuns));
 const metricKey = $derived(metricName || refs.settings.primaryMetric || '');
 const tree = $derived(buildExperimentTree(experiments,runs,Object.fromEntries(Object.entries(metrics).map(([runId,value])=>[runId,value.metrics])),metricKey,refs.settings.metricDirections[metricKey]));
 const latestValue = $derived(latestRun && metricKey ? metrics[latestRun.id]?.metrics[metricKey] : undefined);
 const parentRun = $derived(chosen?.parentExperimentId ? latestDoneRun(runs.filter((run) => run.experimentId === chosen.parentExperimentId)) : null);
 const parentValue = $derived(parentRun && metricKey ? metrics[parentRun.id]?.metrics[metricKey] : undefined);
 const metricState = $derived(metricDelta(typeof latestValue === 'number' && Number.isFinite(latestValue) ? latestValue : null, typeof parentValue === 'number' && Number.isFinite(parentValue) ? parentValue : null, refs.settings.metricDirections[metricKey]));
 const latestCurveRun=$derived([...scopedRuns].sort((a,b)=>b.createdAt-a.createdAt)[0]??null);
 function seriesPoints(series:Array<{step:number;value:number}>|undefined){if(!series?.length)return '';const all=[...(latestCurveRun?metrics[latestCurveRun.id]?.series[metricKey]||[]:[]),...(parentRun?metrics[parentRun.id]?.series[metricKey]||[]:[])].filter(x=>Number.isFinite(x.step)&&Number.isFinite(x.value));if(!all.length)return '';const min=Math.min(...all.map(x=>x.value)),max=Math.max(...all.map(x=>x.value)),first=Math.min(...all.map(x=>x.step)),last=Math.max(...all.map(x=>x.step));return series.filter(x=>Number.isFinite(x.step)&&Number.isFinite(x.value)).map(x=>`${8+(last===first?0:(x.step-first)/(last-first))*584},${88-(max===min?38:((x.value-min)/(max-min))*76)}`).join(' ');}
 function treeDifference(experiment:ResearchExperiment){if(!experiment.parentExperimentId)return '기준선';const done=latestDoneRun(runs.filter(r=>r.experimentId===experiment.id)),parent=latestDoneRun(runs.filter(r=>r.experimentId===experiment.parentExperimentId));const self=done?metrics[done.id]?.metrics[metricKey]:undefined,base=parent?metrics[parent.id]?.metrics[metricKey]:undefined;if(self!==undefined&&base!==undefined)return `${self-base>0?'+':''}${Number((self-base).toPrecision(4))} ${refs.settings.metricUnits[metricKey]||''}`;const node=tree.find(n=>n.experiment.id===experiment.id);return node?.phase==='running'?'실행 중':node?.phase==='failed'?'실패':'결과 없음';}
 const current = (scope:number,p:string,h:string|undefined) => scope===generation && p===id && h===host;
 function setQuery(key:string,value:string|null){const u=new URL(page.url); if(value)u.searchParams.set(key,value);else u.searchParams.delete(key);replaceState(u, page.state);}
 function selectTab(tab:typeof activeTab){activeTab=tab;setQuery('tab',tab);}
 async function refresh(scope=generation,p=id,h=host){if(!current(scope,p,h)||document.visibilityState!=='visible')return;const request=++refreshSequence,version=mutationVersion;const api=researchApi(h);const results=await Promise.allSettled([api.project(p),api.experiments(p),api.runs(p),api.status(),api.refs(p),api.targets(p)]);if(!current(scope,p,h))return;
  if(request!==refreshSequence)return;const [pr,ex,ru,st,rf,tg]=results;
  if(pr.status==='fulfilled')project=pr.value; if(ex.status==='fulfilled'&&version===mutationVersion)experiments=ex.value; if(ru.status==='fulfilled'&&version===mutationVersion)runs=ru.value;
  if(st.status==='fulfilled')status=st.value; if(rf.status==='fulfilled'&&version===mutationVersion)refs=rf.value; if(tg.status==='fulfilled'){targets=tg.value.targets;if(!availableTarget(targets,selectedTarget)?.id)selectedTarget='';else if(!availableTarget(targets,selectedTarget))selectedTarget=availableTarget(targets,selectedTarget)?.id||'';}
  if(pr.status==='rejected'||ex.status==='rejected'||ru.status==='rejected')error='프로젝트 실험 상태를 확인하지 못했어요.';else error='';
  if(!selectedExperiment||!experiments.some(x=>x.id===selectedExperiment)) selectedExperiment=experiments.find(x=>x.id===localStorage.getItem(`research-selection:${h||''}:${p}`))?.id||experiments[0]?.id||'';
 }
 async function refreshFiles(scope=generation,p=id,h=host){try{const found=await researchApi(h).files(p);if(current(scope,p,h))files=found;}catch{if(current(scope,p,h))error='산출물 목록을 확인하지 못했어요.';}}
 async function loadSnapshot(e=selectedExperiment,scope=generation,p=id,h=host){if(!e)return;try{const value=await researchApi(h).snapshot(p,e);if(current(scope,p,h)&&selectedExperiment===e)snapshot=value;}catch{if(current(scope,p,h)&&selectedExperiment===e)snapshot=null;}}
 async function loadMetrics(run:ResearchRun,scope=generation,p=id,h=host){if(metrics[run.id]&&!isRunActive(run.status))return;try{const value=await researchApi(h).metrics(p,run.id);if(current(scope,p,h))metrics={...metrics,[run.id]:value};}catch{/* unavailable until provider support exists */}}
 async function toggleRun(run:ResearchRun){const opening=!openRuns.includes(run.id);openRuns=opening?[run.id]:[];selectedRun=opening?run.id:'';logStart=0;log=null;logError='';followLog=true;logToken++;if(opening){await loadLog(run.id,0);const scope=generation;void loadMetrics(run,scope,id,host);}}
 async function loadLog(runId=selectedRun,start=logStart){const scope=generation,p=id,h=host,token=++logToken;if(!runId||document.visibilityState!=='visible')return;logError='';try{const value=await researchApi(h).log(p,runId,start,start?log?.ident:undefined);if(current(scope,p,h)&&token===logToken&&selectedRun===runId&&logStart===start){if(value.reset){log=null;logStart=0;void loadLog(runId,0);}else if(followLog&&typeof value.total==='number'&&value.total>value.end){logStart=Math.max(0,value.total-65536);void loadLog(runId,logStart);}else{log=value;if(followLog)requestAnimationFrame(()=>{if(current(scope,p,h)&&token===logToken&&logPanel)logPanel.scrollTop=logPanel.scrollHeight;});}}}catch(cause){if(current(scope,p,h)&&token===logToken)logError=cause instanceof Error?cause.message:'실행 로그를 불러오지 못했어요.';}}
 async function createExperiment(event:SubmitEvent){event.preventDefault();if(busy||!title.trim())return;const scope=generation,p=id,h=host;busy=true;try{const created=await researchApi(h).createExperiment(p,{title:title.trim(),...(description.trim()?{description:description.trim()}:{}),...(command.trim()?{runCommand:command.trim()}:{}),...(parentId?{parentId}:{})});if(!current(scope,p,h))return;title='';description='';command='';const newChild=created.find(child=>!experiments.some(existing=>existing.id===child.id));if(newChild){selectedExperiment=newChild.id;setQuery('experiment',newChild.id);}await refresh(scope,p,h);}catch(cause){if(current(scope,p,h))error=`실험 생성 실패: ${cause instanceof Error?cause.message:''}`;}finally{if(current(scope,p,h))busy=false;}}
 async function startRun(){const target=availableTarget(targets,selectedTarget); if(!chosen||!target||busy||!status?.connected||status.capabilities?.expectedCommit!==true)return;const scope=generation,p=id,h=host,e=chosen.id;busy=true;error='';try{const api=researchApi(h);const snap=await api.snapshot(p,e);if(!current(scope,p,h)||selectedExperiment!==e)return;if(!/^[a-f0-9]{40,64}$/i.test(snap.headCommit))throw new Error('스냅샷 커밋이 유효하지 않아요.');if(!confirm(`이 실험을 실행할까요?\n\n호스트: ${h||location.origin}\n대상: ${target.label}\n브랜치: ${snap.branch}\n커밋: ${snap.headCommit}\n미커밋 변경: ${snap.uncommittedCount===null?'확인할 수 없음':snap.uncommittedCount}\n\n실행 기준 SHA를 확인해 주세요.`))return;if(targets.find(x=>x.id===selectedTarget)?.backend==='ssh'){await api.requestApproval(p,e,snap.headCommit,selectedTarget);if(current(scope,p,h))await refresh(scope,p,h);return;}const started=await api.startRun(p,e,snap.headCommit,target.id);if(!current(scope,p,h))return;if(selectedExperiment!==e){await refresh(scope,p,h);return;}selectedRun=started.id;openRuns=[started.id];logStart=0;log=null;logToken++;await refresh(scope,p,h);void loadLog(started.id,0);}catch(cause){if(current(scope,p,h))error=`실행 요청 실패. 상태를 새로고침해 주세요. ${cause instanceof Error?cause.message:''}`;}finally{if(current(scope,p,h))busy=false;}}
 async function cancelRun(run:ResearchRun){if(pendingCancel.includes(run.id)||!confirm(`실행 ${seq.get(run.id)} 취소할까요?`))return;const scope=generation,p=id,h=host;pendingCancel=[...pendingCancel,run.id];try{await researchApi(h).cancelRun(p,run.id);if(current(scope,p,h))await refresh(scope,p,h);}catch(cause){if(current(scope,p,h))error=`취소 상태 확인 필요: ${cause instanceof Error?cause.message:''}`;}finally{if(current(scope,p,h))pendingCancel=pendingCancel.filter(x=>x!==run.id);}}
 async function reconnect(run:ResearchRun){if(pendingReconnect.includes(run.id))return;const scope=generation,p=id,h=host;pendingReconnect=[...pendingReconnect,run.id];try{await researchApi(h).reconnect(p,run.id);if(current(scope,p,h))await refresh(scope,p,h);}catch(cause){if(current(scope,p,h))error=`실행 호스트 재연결 실패: ${cause instanceof Error?cause.message:''}`;}finally{if(current(scope,p,h))pendingReconnect=pendingReconnect.filter(id=>id!==run.id);}}
 async function createChild(){if(!chosen||busy)return;const parent=chosen;const n=experiments.filter(x=>x.parentExperimentId===parent.id).length+1;title=`${parent.title||parent.slug} 파생 ${n}`;parentId=parent.id;command=parent.runCommand;await createExperiment({preventDefault(){}} as SubmitEvent);}
 async function decideApproval(approvalId:string,approved:boolean){const scope=generation,p=id,h=host;if(!confirm(approved?'이 실행 승인을 제출할까요?':'실행 승인 요청을 거부할까요?'))return;busy=true;try{await researchApi(h).approve(p,approvalId,approved);if(current(scope,p,h))await refresh(scope,p,h);}catch(cause){if(current(scope,p,h))error=`승인 상태를 확인하지 못했어요. ${cause instanceof Error?cause.message:''}`;}finally{if(current(scope,p,h))busy=false;}}
 async function saveExperimentLinks(event:SubmitEvent){event.preventDefault();if(!chosen)return;const version=++mutationVersion;const form=new FormData(event.currentTarget as HTMLFormElement);const path=String(form.get('paperPath')||'').trim(),section=String(form.get('paperSection')||'').trim();const scope=generation,p=id,h=host;const prior=refs.experiments[chosen.id];try{const next=await researchApi(h).saveLinks(p,chosen.id,{paperRef:path?{path,anchor:section||undefined}:null,literatureIds:selectedPaperId?[...new Set([...(prior?.literatureIds||[]),selectedPaperId])]:prior?.literatureIds||[],artifactPaths:selectedArtifactPath?[...new Set([...(prior?.artifactPaths||[]),selectedArtifactPath])]:prior?.artifactPaths||[]});if(!current(scope,p,h)||version!==mutationVersion)return;refs=next;}catch(cause){if(current(scope,p,h))error=`연결 저장 실패: ${cause instanceof Error?cause.message:''}`;}}
 async function saveMetric(){if(!metricName.trim())return;const version=++mutationVersion;const scope=generation,p=id,h=host;try{const next=await researchApi(h).settings(p,{...refs.settings,primaryMetric:metricName.trim(),metricDirections:{...refs.settings.metricDirections,[metricName.trim()]:metricDirection},metricUnits:{...refs.settings.metricUnits,[metricName.trim()]:metricUnit.trim()}});if(!current(scope,p,h)||version!==mutationVersion)return;refs=next;}catch(cause){if(current(scope,p,h))error=`지표 설정 저장 실패: ${cause instanceof Error?cause.message:''}`;}}
 async function launchChat(){if(!selectedExperiment||chatBusy)return;const scope=generation,p=id,h=host,e=selectedExperiment;chatBusy=true;chatError='';try{const result=await researchApi(h).startChat(p,e,crypto.randomUUID());if(!current(scope,p,h))return;const next=await researchApi(h).refs(p);if(!current(scope,p,h))return;refs=next;if(selectedExperiment!==e)return;chatDraft=result.draftContext?JSON.stringify(result.draftContext,null,2):'';chatError=`실제 세션 생성됨: ${result.sessionId} · ${result.host}`;}catch(cause){if(current(scope,p,h))chatError=cause instanceof Error?cause.message:'실험 대화를 만들지 못했어요.';}finally{if(current(scope,p,h))chatBusy=false;}}
 async function openArtifact(file:ResearchFile,trigger:HTMLButtonElement){const scope=generation,p=id,h=host,token=++artifactToken;try{const uri=researchApi(h).artifactUrl(p,file.path,true);if(!/\.(png|jpe?g|gif|webp|avif|txt|md)$/i.test(file.name)){artifactPreview?.openPreview({kind:'file',name:file.name,uri},trigger);return;}const response=await fetch(uri,{credentials:'include',signal:AbortSignal.timeout(20000)});if(!response.ok)throw new Error(`Artifact ${response.status}`);const reader=response.body?.getReader();if(!reader)throw new Error('Empty artifact response');let size=0;const chunks:Array<Uint8Array<ArrayBuffer>>=[];while(true){const chunk=await reader.read();if(chunk.done)break;size+=chunk.value.length;if(size>10*1024*1024){await reader.cancel();throw new Error('Preview limit: 10 MiB');}chunks.push(chunk.value);}const blob=new Blob(chunks,{type:response.headers.get('content-type')||'application/octet-stream'});const result=await readAttachmentFiles([new File([blob],file.name,{type:blob.type})],[],0);if(!current(scope,p,h)||token!==artifactToken)return;if(result.error)throw new Error(result.error);if(result.attachments[0])artifactPreview?.openPreview(result.attachments[0].attachment,trigger);}catch(cause){if(current(scope,p,h)&&token===artifactToken)error=cause instanceof Error?cause.message:'Artifact preview failed';}}
 async function openDashboard(){const scope=generation,p=id,h=host;try{const result=await researchApi(h).dashboard(p,location.origin);if(current(scope,p,h))dashboardUrl=result.url;}catch(cause){if(current(scope,p,h))error=`읽기 전용 대시보드를 열지 못했어요: ${cause instanceof Error?cause.message:''}`;}}
 function selectExperiment(e:string){selectedExperiment=e;selectedPaperId='';selectedArtifactPath='';localStorage.setItem(`research-selection:${host||''}:${id}`,e);selectedRun='';openRuns=[];log=null;logToken++; setQuery('experiment',e);snapshot=null;void loadSnapshot(e);}
 function pageLog(direction:number){if(!log)return;followLog=false;logStart=Math.max(0,direction<0?logStart-65536:log.end);void loadLog(selectedRun,logStart);}
 $effect(()=>{const p=id,h=host,scope=++generation;refreshSequence++;mutationVersion++;const requested=page.url.searchParams.get('experiment');const tab=page.url.searchParams.get('tab');if(['overview','experiments','literature','chat'].includes(tab||''))activeTab=tab as typeof activeTab;selectedExperiment=requested||localStorage.getItem(`research-selection:${h||''}:${p}`)||'';project=null;status=null;experiments=[];runs=[];files=[];refs={literature:[],experiments:{},settings:{primaryMetric:null,metricDirections:{},metricUnits:{}}};targets=[];selectedExperiment='';selectedRun='';openRuns=[];metrics={};snapshot=null;error='';busy=false;chatBusy=false;pendingCancel=[];pendingReconnect=[];title='';description='';command='';parentId='';metricName='';metricUnit='';metricDirection='higher';chatDraft='';chatError='';dashboardUrl='';log=null;logStart=0;logError='';logToken++;selectedPaperId='';selectedArtifactPath='';selectedTarget='';void refresh(scope,p,h);void refreshFiles(scope,p,h);const tick=()=>{if(document.visibilityState==='visible'){void refresh(scope,p,h);if(selectedRun&&openRuns.includes(selectedRun))void loadLog(selectedRun,logStart);}};timer=setInterval(tick,5000);const visible=()=>{if(document.visibilityState==='visible')tick();};document.addEventListener('visibilitychange',visible);return()=>{generation++;logToken++;if(timer)clearInterval(timer);document.removeEventListener('visibilitychange',visible);};});
 $effect(()=>{const e=selectedExperiment,actual=runs,latest=latestCurveRun,parent=parentRun,scope=generation,p=id,h=host;untrack(()=>{if(e)void loadSnapshot(e,scope,p,h);for(const run of actual){if(['done','best'].includes(run.status)||run.id===latest?.id)void loadMetrics(run,scope,p,h);}if(parent)void loadMetrics(parent,scope,p,h);});});
</script>

<svelte:head><title>{project?.name||'연구 프로젝트'} · Postudio</title></svelte:head>
<div class="research-ui min-h-0 flex-1 overflow-y-auto px-4 py-6 sm:px-8">
 <div class="mx-auto max-w-6xl space-y-4">
  <a class="text-sm" href="/research{host?`?host=${encodeURIComponent(host)}`:''}">연구 워크스페이스</a>
  <header class="research-card"><p class="eyebrow">{project?.repoPath||'저장소 경로 확인 중'}</p><h1>{project?.name||'연구 프로젝트'}</h1><div class="engine"><span aria-label={status?.connected?'연결됨':'연결 안 됨'} class:online={status?.connected}></span>엔진 {status?.connected?'연결됨':'연결 확인 필요'}{#if status?.version} · {status.version}{/if}<span class="mono">계약 {status?.capabilities?.postudioContract||0}</span><button class="secondary" onclick={()=>void refresh()}>새로고침</button><button class="secondary" disabled={!status?.connected||!status.capabilities?.dashboard} onclick={()=>void openDashboard()}>대시보드</button>{#if dashboardUrl}<a href={dashboardUrl} target="_blank" rel="noopener noreferrer">읽기 전용 대시보드 열기</a>{/if}</div>{#if status?.error}<p role="status">{status.error}</p>{/if}</header>
  {#if error}<p role="alert" class="error-note">{error}</p>{/if}
  <div class="tabs" aria-label="프로젝트 탭" role="tablist" tabindex="-1" onkeydown={(event)=>{const tabs=Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('button[role=tab]'));const i=tabs.indexOf(document.activeElement as HTMLButtonElement);const next=event.key==='ArrowRight'?(i+1)%tabs.length:event.key==='ArrowLeft'?(i+tabs.length-1)%tabs.length:event.key==='Home'?0:event.key==='End'?tabs.length-1:-1;if(next>=0){event.preventDefault();tabs[next].focus();tabs[next].click();}}}>{#each [{id:'overview',label:'개요'},{id:'experiments',label:'실험'},{id:'literature',label:'문헌'},{id:'chat',label:'대화'}] as tab}<button role="tab" aria-selected={activeTab===tab.id} tabindex={activeTab===tab.id?0:-1} class:active={activeTab===tab.id} onclick={()=>selectTab(tab.id as typeof activeTab)}>{tab.label}{#if tab.id==='experiments'}<span>{runs.filter(x=>['queued','running','starting','submitting'].includes(x.status)).length}</span>{:else if tab.id==='literature'}<span>{refs.literature.length}</span>{/if}</button>{/each}</div>
  {#if activeTab==='overview'}
   <section class="research-card"><p class="eyebrow">프로젝트 요약</p><h2>{project?.name}</h2><p class="mono">{project?.repoPath}</p><div class="summary-grid"><span>{experiments.length} 실험</span><span>{runs.length} 실행</span><span>{refs.literature.length} 연결 문헌</span><span>{files.length} 실제 파일</span></div><p>실행 기록과 파일 목록은 서버가 반환한 실제 데이터만 표시해요.</p><button class="secondary" onclick={()=>selectTab('experiments')}>실험 열기</button></section>
   <TargetBindings {host} projectId={id} onChange={()=>{mutationVersion++;void refresh();}}/>
  {:else if activeTab==='literature'}
   <ProjectLiterature {host} projectId={id} {refs} {experiments} onChange={(event)=>{if(event.projectId===id&&event.host===host){mutationVersion++;refs=event.refs;}}} />
  {:else if activeTab==='chat'}
   <section class="research-card"><h2>실험 대화</h2><label>실험 선택<select value={selectedExperiment} onchange={(event)=>selectExperiment(event.currentTarget.value)}><option value="">실험 선택</option>{#each experiments as experiment}<option value={experiment.id}>{experiment.title||experiment.slug}</option>{/each}</select></label><p>선택한 실험의 실제 작업 공간과 연결된 Distill 세션을 만듭니다.</p><button class="primary" disabled={!selectedExperiment||chatBusy||!status?.connected} onclick={()=>void launchChat()}>{chatBusy?'세션 생성 중…':'실험 대화 시작'}</button>{#if chatError}<p role="status">{chatError}</p>{/if}{#if chatDraft}<label>실험 컨텍스트 미리보기<textarea readonly value={chatDraft} rows="6"></textarea></label><p>대화에서 요청을 보낼 때 실험 ID·브랜치·최신 실행을 자동으로 첨부해요. 세션을 만드는 것만으로 모델을 실행하지 않아요.</p>{/if}<h3>실제 연결된 세션</h3>{#each refs.experiments[selectedExperiment]?.sessionIds||[] as sessionId}<a href={`/s/${encodeURIComponent(sessionId)}${host?`?host=${encodeURIComponent(host)}`:''}`}>세션 {sessionId} 열기</a>{:else}<p>연결된 세션 없음</p>{/each}{#if refs.experiments[selectedExperiment]?.distillSessionId}<p>기본 세션: {refs.experiments[selectedExperiment]?.distillSessionId}</p>{/if}</section>
  {:else}
   <div class="research-grid">
    <nav class="research-card research-tree" aria-label="실험 트리">{#if tree.length===0}<p>실험이 아직 없어요.</p>{:else}{#each tree as node (node.experiment.id)}{@const experiment=node.experiment}<button class="research-node" aria-current={selectedExperiment===experiment.id?'true':undefined} aria-label={`${experiment.title||experiment.slug}: ${phaseLabel(node.phase)}${node.value===null?'':`, ${metricKey} ${node.value}`}${node.best?', 최고 지표':''}`} style={`--tree-depth:${node.depth}`} onclick={()=>selectExperiment(experiment.id)}><span class="tree-dot" class:done={node.phase==='done'} class:failed={node.phase==='failed'} class:running={node.phase==='running'} class:draft={node.phase==='draft'}></span><span>{experiment.title||experiment.slug}</span><small>{phaseLabel(node.phase)} · <span class:better={node.delta==='better'} class:worse={node.delta==='worse'}>{treeDifference(experiment)}</span>{node.best?' · 최고':''}</small><code>{experiment.branchName}</code></button>{/each}{/if}</nav>
    <section class="space-y-4" aria-label="실험 상세">
     {#if chosen}
      <section class="research-card"><p class="eyebrow">{chosen.parentExperimentId?'자식 실험':'기준선'}</p><h1>{chosen.title||chosen.slug}</h1><p class="mono">{chosen.branchName}</p>{#if chosen.parentExperimentId}<p>부모: {experiments.find(x=>x.id===chosen.parentExperimentId)?.title||chosen.parentExperimentId}</p>{/if}<button class="secondary" disabled={busy||!status?.connected} onclick={()=>void createChild()}>자식 실험</button><p>{chosen.description||'설명 없음'}</p><div class="command">{chosen.runCommand||'명령 확인 필요'}</div>
       <div class="targets" role="radiogroup" aria-label="실행 대상">{#each targets as target}<label><input type="radio" name="research-target" value={target.id} bind:group={selectedTarget} disabled={!target.available}/>{target.label}{target.available?'':' · 사용 불가'}</label>{/each}{#if targets.length===0}<span>실행 대상 확인 불가</span>{/if}</div>
       <button class="primary" disabled={!status?.connected||status.capabilities?.expectedCommit!==true||busy||!availableTarget(targets,selectedTarget)} onclick={()=>void startRun()}>실행 요청</button>
       {#if snapshot}<p class="snapshot" role="note">실행하면 커밋 {snapshot.headCommit} 스냅샷을 보내요.{#if snapshot.uncommittedCount===null} 커밋하지 않은 변경 수는 확인할 수 없어요.{:else if snapshot.uncommittedCount>0} <span class="dirty-notice">커밋하지 않은 변경 {snapshot.uncommittedCount}개는 실행에 포함되지 않아요.</span>{/if}</p>{:else}<p class="snapshot" role="note">실행 요청 전에 실제 스냅샷을 확인합니다. 미지원 기능일 때 실행하지 않습니다.</p>{/if}
       {#each (refs.approvals||[]).filter(a=>a.experimentId===chosen?.id) as approval (approval.id)}<div class="approval"><span>승인 요청 · {approval.status} · {approval.targetId} · {approval.expectedCommit}</span>{#if approval.status==='pending'}<button class="secondary" disabled={busy} onclick={()=>void decideApproval(approval.id,true)}>승인 및 제출</button><button class="secondary" disabled={busy} onclick={()=>void decideApproval(approval.id,false)}>거부</button>{/if}{#if approval.error}<p role="alert">{approval.error}</p>{/if}</div>{/each}
      </section>
      <section class="research-card"><h2>실험 만들기</h2><form class="create-form" onsubmit={createExperiment}><label>제목<input bind:value={title} required maxlength="160"/></label><label>가설<textarea bind:value={description} rows="2"></textarea></label><label>실행 명령<input bind:value={command}/></label><label>부모 실험<select bind:value={parentId}><option value="">기준선 실험</option>{#each experiments as exp}<option value={exp.id}>{exp.title||exp.slug}</option>{/each}</select></label><button class="secondary" disabled={busy||!status?.connected}>실험 만들기</button></form></section>
      <section class="research-card"><div class="card-heading"><h2>지표 결과</h2><span>실제 Trackio 값만 표시</span></div>
       {#if !latestDoneRun(scopedRuns)}<p>완료된 실행이나 실제 지표가 없어요.</p>
       {:else}
        {@const completed = latestDoneRun(scopedRuns)!}
        {#if !metrics[completed.id]}<button class="secondary" onclick={() => void loadMetrics(completed, generation, id, host)}>실제 지표 불러오기</button>
        {:else}
         {@const metricData = metrics[completed.id]}
         <div class="metric-settings"><select bind:value={metricName} aria-label="표시할 지표"><option value="">지표 선택</option>{#each Object.keys(metricData.metrics) as name}<option value={name}>{name}</option>{/each}</select><input bind:value={metricUnit} aria-label="지표 단위" placeholder="단위"/><select bind:value={metricDirection} aria-label="지표 방향"><option value="higher">높을수록 좋음</option><option value="lower">낮을수록 좋음</option></select><button class="secondary" onclick={() => void saveMetric()} disabled={!metricName}>저장</button></div>
         <div role="table" aria-label="부모 실험 지표 비교"><div class="metric-row" role="row"><b role="columnheader">지표</b><span role="columnheader">부모</span><span role="columnheader">이 실험</span><span role="columnheader">차이</span></div>{#each Object.entries(metricData.metrics) as [name,value]}{@const parent=parentRun?metrics[parentRun.id]?.metrics[name]:undefined}{@const difference=parent===undefined?null:value-parent}{@const tone=metricDelta(value,parent??null,refs.settings.metricDirections[name])}<div class="metric-row" role="row"><b role="cell">{name}</b><span role="cell">{parent??'—'}</span><span role="cell">{value}</span><span role="cell" class:better={tone==='better'} class:worse={tone==='worse'}>{difference===null?'—':`${difference>0?'+':''}${Number(difference.toPrecision(4))}`} {refs.settings.metricUnits[name]||''}</span></div>{/each}</div>
         {#if metricKey && latestCurveRun && metrics[latestCurveRun.id]?.series[metricKey]?.length}<svg viewBox="0 0 600 96" role="img" aria-label={`${metricKey} 손실 곡선, 부모 최신 완료 실행과 비교`}><polyline fill="none" stroke="var(--blue)" stroke-width="2" points={seriesPoints(metrics[latestCurveRun.id]?.series[metricKey])}/>{#if parentRun}<polyline fill="none" stroke="#8a8a90" stroke-dasharray="5 4" points={seriesPoints(metrics[parentRun.id]?.series[metricKey])}/>{/if}</svg>{/if}
         {#if metricData.errors.length}<p role="status">{metricData.errors.join(' · ')}</p>{/if}
        {/if}
       {/if}
      </section>
      <section class="research-card"><h2>실행 기록</h2>{#if scopedRuns.length===0}<p>이 실험의 실행 기록이 없어요.</p>{:else}<div class="run-list">{#each [...scopedRuns].sort((a,b)=>b.createdAt-a.createdAt) as run (run.id)}<article class="run-card"><button class="run-toggle" aria-label={`실행 ${seq.get(run.id)} ${runLabel(run.status)} 로그 ${openRuns.includes(run.id)?'접기':'열기'}`} aria-expanded={openRuns.includes(run.id)} onclick={()=>void toggleRun(run)}><b>#{seq.get(run.id)}</b><span class="chip" class:phase-running={isRunActive(run.status)} class:phase-done={['done','best'].includes(run.status)} class:phase-failed={run.status==='failed'}>{runLabel(run.status)}</span><code>{run.commitSha||'커밋 확인 불가'}</code><time>{new Date(run.createdAt).toLocaleString()}</time><span>{run.exitCode===null?'':`종료 ${run.exitCode}`}</span></button>{#if run.contact&&runContactNotice(run.contact.type)}<p class="connection" role="status">{pendingReconnect.includes(run.id)?'다시 연결하는 중…':run.contact.type==='unreachable'?'연결 끊김 · 마지막 신호 확인할 수 없음':runContactNotice(run.contact.type)}</p>{#if isRunActive(run.status)||run.status==='lost'}<button class="secondary" disabled={pendingReconnect.includes(run.id)} onclick={()=>void reconnect(run)}>{pendingReconnect.includes(run.id)?'다시 연결하는 중…':'다시 연결'}</button>{/if}{/if}{#if run.status==='lost'}<p role="status">실행 호스트 상태 확인 불가</p>{:else if run.status==='cancelled'}<p role="status">실행 취소됨</p>{/if}{#if run.cancelling||pendingCancel.includes(run.id)}<p role="status">실행 취소 확인 중</p>{:else if isRunActive(run.status)}<button class="secondary" onclick={()=>void cancelRun(run)}>실행 취소</button>{/if}{#if openRuns.includes(run.id)}<div class="log-box" bind:this={logPanel} onscroll={(event)=>{const node=event.currentTarget;followLog=node.scrollHeight-node.scrollTop-node.clientHeight<32;}}><div class="log-actions"><button disabled={!logStart} onclick={()=>pageLog(-1)}>이전 64 KB</button><button disabled={!log||log.total===undefined||log.end>=log.total} onclick={()=>pageLog(1)}>다음 64 KB</button></div>{#if logError}<p role="alert">{logError}</p>{:else if log}<pre>{#each log.text.split('\n') as line}<span class:sys={line.startsWith('[orx]')} class:err={!line.startsWith('[orx]')&&/Error|Exception|out of memory/.test(line)}>{line}{'\n'}</span>{/each}</pre>{:else}<p>로그를 불러오는 중이에요.</p>{/if}</div>{/if}</article>{/each}</div>{/if}</section>
      <div class="research-panels"><section class="research-card"><h2>산출물</h2>{#if files.length===0}<p>실제 파일이 없거나 확인되지 않았어요.</p>{:else}<ul class="research-artifacts">{#each files as file (file.path)}<li>{#if /\.(png|jpe?g|gif|webp|avif)$/i.test(file.name)}<img class="artifact-thumb" src={researchApi(host).artifactUrl(id,file.path)} alt={file.name} loading="lazy"/>{:else}<span class="artifact-doc">{file.name.split('.').pop()?.toUpperCase().slice(0,6)||'FILE'}</span>{/if}<button class="secondary" type="button" onclick={(event)=>void openArtifact(file,event.currentTarget)}>{file.path}</button><a href={researchApi(host).artifactUrl(id,file.path,true)}>다운로드</a><span>{file.kind||'파일'} · {file.size??0} B</span></li>{/each}</ul>{/if}<button class="secondary" onclick={()=>void refreshFiles()}>파일 새로고침</button></section><section class="research-card connection-links"><h2>연결</h2>{#if currentLink.distillSessionId}<a href={`/s/${encodeURIComponent(currentLink.distillSessionId)}${host?`?host=${encodeURIComponent(host)}`:''}`}>설계한 대화</a>{/if}{#if currentLink.paperRef}<p>논문 참조: {currentLink.paperRef.path} {currentLink.paperRef.anchor||''}</p>{/if}{#each refs.experiments[chosen?.id||'']?.literatureIds||[] as paperId}{@const paper=refs.literature.find(item=>item.id===paperId)}{#if paper}<p><a href={paper.url} target="_blank" rel="noopener noreferrer">{paper.title}</a></p>{/if}{/each}{#each refs.experiments[chosen?.id||'']?.artifactPaths||[] as artifactPath}<p><a href={researchApi(host).artifactUrl(id,artifactPath)}>{artifactPath}</a></p>{/each}{#key `${host||''}:${id}:${selectedExperiment}`}<form onsubmit={saveExperimentLinks}><label>연결할 문헌<select bind:value={selectedPaperId}><option value="">문헌 선택</option>{#each refs.literature as paper}<option value={paper.id}>{paper.title}</option>{/each}</select></label><label>연결할 실제 파일<select bind:value={selectedArtifactPath}><option value="">파일 선택</option>{#each files.filter(file=>file.kind!=='directory') as file}<option value={file.path}>{file.path}</option>{/each}</select></label><label>논문 원고 경로<input name="paperPath" value={currentLink.paperRef?.path||''} placeholder="paper/main.tex"/></label><label>참조 위치<input name="paperSection" value={currentLink.paperRef?.anchor||''} placeholder="Table 2"/></label><button class="secondary" type="submit" disabled={!status?.connected}>연결 저장</button></form>{/key}</section></div>
     {:else}<section class="research-card"><h2>아직 실험이 없어요</h2><p>기준선 실험을 하나 만들면, 거기서 가설별로 자식 실험을 뻗어 나가며 결과를 비교할 수 있어요.</p><form class="create-form" onsubmit={createExperiment}><label>제목<input bind:value={title} required maxlength="160"/></label><label>가설<textarea bind:value={description}></textarea></label><label>실행 명령<input bind:value={command}/></label><button class="primary" disabled={busy||!status?.connected}>기준선 실험 만들기</button></form></section>{/if}
    </section>
   </div>
  {/if}
 </div>
<AttachmentPreview items={[]} bind:this={artifactPreview}/>
</div>

